138: // this one is needed for knowing the destination addr of udp packet
139: // an udp socket can only bind to one port, and that port never changes
140: // this function returns ONLY the IP address, not any port
141: int bsd_udp_packet_buffer_local_ip(void *msgvec, int index, char *ip) {
142: #if defined(_WIN32) || defined(__APPLE__)
143:     return 0; // not supported
144: #else
145:     struct msghdr *mh = &((struct mmsghdr *) msgvec)[index].msg_hdr;
146:     for (struct cmsghdr *cmsg = CMSG_FIRSTHDR(mh); cmsg != NULL; cmsg = CMSG_NXTHDR(mh, cmsg)) {
147:         // Linux ipv4
148:     #ifdef IP_PKTINFO
149:         if (cmsg->cmsg_level == IPPROTO_IP && cmsg->cmsg_type == IP_PKTINFO) {
150:             struct in_pktinfo *pi = (struct in_pktinfo *) CMSG_DATA(cmsg);
151:             memcpy(ip, &pi->ipi_addr, 4);
152:             return 4;
153:         }
154:         // FreeBSD ipv4
155:     #elif IP_RECVDSTADDR
156:         if (cmsg->cmsg_level == IPPROTO_IP && cmsg->cmsg_type == IP_RECVDSTADDR) {
157:             struct in_addr *addr = (struct in_addr *) CMSG_DATA(cmsg);
158:             memcpy(ip, addr, 4);
159:             return 4;
160:         }
161:     #endif
162: 
163:         // Linux, FreeBSD ipv6
164:         if (cmsg->cmsg_level == IPPROTO_IPV6 && cmsg->cmsg_type == IPV6_PKTINFO) {
165:             struct in6_pktinfo *pi6 = (struct in6_pktinfo *) CMSG_DATA(cmsg);
166:             memcpy(ip, &pi6->ipi6_addr, 16);
167:             return 16;
168:         }
169:     }
170: 
171:     return 0; // no length
172: 
173: #endif
174: }
