203: void bsd_udp_buffer_set_packet_payload(struct us_udp_packet_buffer_t *send_buf, int index, int offset, void *payload, int length, void *peer_addr) {
204: #if defined(_WIN32) || defined(__APPLE__)
205:     struct us_internal_udp_packet_buffer *packet_buffer = (struct us_internal_udp_packet_buffer *) send_buf;
206: 
207:     memcpy(packet_buffer->buf[index], payload, length);
208:     memcpy(&packet_buffer->addr[index], peer_addr, sizeof(struct sockaddr_storage));
209: 
210:     packet_buffer->len[index] = length;
211: #else
212:     //printf("length: %d, offset: %d\n", length, offset);
213: 
214:     struct mmsghdr *ss = (struct mmsghdr *) send_buf;
215: 
216:     // copy the peer address
217:     memcpy(ss[index].msg_hdr.msg_name, peer_addr, /*ss[index].msg_hdr.msg_namelen*/ sizeof(struct sockaddr_in));
218: 
219:     // set control length to 0
220:     ss[index].msg_hdr.msg_controllen = 0;
221: 
222:     // copy the payload
223:     
224:     ss[index].msg_hdr.msg_iov->iov_len = length + offset;
225: 
226: 
227:     memcpy(((char *) ss[index].msg_hdr.msg_iov->iov_base) + offset, payload, length);
228: #endif
229: }
