466: // return LIBUS_SOCKET_ERROR or the fd that represents listen socket
467: // listen both on ipv6 and ipv4
468: LIBUS_SOCKET_DESCRIPTOR bsd_create_listen_socket(const char *host, int port, int options) {
469:     struct addrinfo hints, *result;
470:     memset(&hints, 0, sizeof(struct addrinfo));
471: 
472:     hints.ai_flags = AI_PASSIVE;
473:     hints.ai_family = AF_UNSPEC;
474:     hints.ai_socktype = SOCK_STREAM;
475: 
476:     char port_string[16];
477:     snprintf(port_string, 16, "%d", port);
478: 
479:     if (getaddrinfo(host, port_string, &hints, &result)) {
480:         return LIBUS_SOCKET_ERROR;
481:     }
482: 
483:     LIBUS_SOCKET_DESCRIPTOR listenFd = LIBUS_SOCKET_ERROR;
484:     struct addrinfo *listenAddr;
485:     for (struct addrinfo *a = result; a && listenFd == LIBUS_SOCKET_ERROR; a = a->ai_next) {
486:         if (a->ai_family == AF_INET6) {
487:             listenFd = bsd_create_socket(a->ai_family, a->ai_socktype, a->ai_protocol);
488:             listenAddr = a;
489:         }
490:     }
491: 
492:     for (struct addrinfo *a = result; a && listenFd == LIBUS_SOCKET_ERROR; a = a->ai_next) {
493:         if (a->ai_family == AF_INET) {
494:             listenFd = bsd_create_socket(a->ai_family, a->ai_socktype, a->ai_protocol);
495:             listenAddr = a;
496:         }
497:     }
498: 
499:     if (listenFd == LIBUS_SOCKET_ERROR) {
500:         freeaddrinfo(result);
501:         return LIBUS_SOCKET_ERROR;
502:     }
503: 
504:     if (port != 0) {
505:         /* Otherwise, always enable SO_REUSEPORT and SO_REUSEADDR _unless_ options specify otherwise */
506: #ifdef _WIN32
507:         if (options & LIBUS_LISTEN_EXCLUSIVE_PORT) {
508:             int optval2 = 1;
509:             setsockopt(listenFd, SOL_SOCKET, SO_EXCLUSIVEADDRUSE, (void *) &optval2, sizeof(optval2));
510:         } else {
511:             int optval3 = 1;
512:             setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, (void *) &optval3, sizeof(optval3));
513:         }
514: #else
515:     #if /*defined(__linux) &&*/ defined(SO_REUSEPORT)
516:         if (!(options & LIBUS_LISTEN_EXCLUSIVE_PORT)) {
517:             int optval = 1;
518:             setsockopt(listenFd, SOL_SOCKET, SO_REUSEPORT, (void *) &optval, sizeof(optval));
519:         }
520:     #endif
521:         int enabled = 1;
522:         setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, (void *) &enabled, sizeof(enabled));
523: #endif
524: 
525:     }
526:     
527: #ifdef IPV6_V6ONLY
528:     int disabled = 0;
529:     setsockopt(listenFd, IPPROTO_IPV6, IPV6_V6ONLY, (void *) &disabled, sizeof(disabled));
530: #endif
531: 
532:     if (bind(listenFd, listenAddr->ai_addr, (socklen_t) listenAddr->ai_addrlen) || listen(listenFd, 512)) {
533:         bsd_close_socket(listenFd);
534:         freeaddrinfo(result);
535:         return LIBUS_SOCKET_ERROR;
536:     }
537: 
538:     freeaddrinfo(result);
539:     return listenFd;
540: }
