586: LIBUS_SOCKET_DESCRIPTOR bsd_create_udp_socket(const char *host, int port) {
587:     struct addrinfo hints, *result;
588:     memset(&hints, 0, sizeof(struct addrinfo));
589: 
590:     hints.ai_flags = AI_PASSIVE;
591:     hints.ai_family = AF_UNSPEC;
592:     hints.ai_socktype = SOCK_DGRAM;
593: 
594:     char port_string[16];
595:     snprintf(port_string, 16, "%d", port);
596: 
597:     if (getaddrinfo(host, port_string, &hints, &result)) {
598:         return LIBUS_SOCKET_ERROR;
599:     }
600: 
601:     LIBUS_SOCKET_DESCRIPTOR listenFd = LIBUS_SOCKET_ERROR;
602:     struct addrinfo *listenAddr;
603:     for (struct addrinfo *a = result; a && listenFd == LIBUS_SOCKET_ERROR; a = a->ai_next) {
604:         if (a->ai_family == AF_INET6) {
605:             listenFd = bsd_create_socket(a->ai_family, a->ai_socktype, a->ai_protocol);
606:             listenAddr = a;
607:         }
608:     }
609: 
610:     for (struct addrinfo *a = result; a && listenFd == LIBUS_SOCKET_ERROR; a = a->ai_next) {
611:         if (a->ai_family == AF_INET) {
612:             listenFd = bsd_create_socket(a->ai_family, a->ai_socktype, a->ai_protocol);
613:             listenAddr = a;
614:         }
615:     }
616: 
617:     if (listenFd == LIBUS_SOCKET_ERROR) {
618:         freeaddrinfo(result);
619:         return LIBUS_SOCKET_ERROR;
620:     }
621: 
622:     if (port != 0) {
623:         /* Should this also go for UDP? */
624:         int enabled = 1;
625:         setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, (void *) &enabled, sizeof(enabled));
626:     }
627:     
628: #ifdef IPV6_V6ONLY
629:     int disabled = 0;
630:     setsockopt(listenFd, IPPROTO_IPV6, IPV6_V6ONLY, (void *) &disabled, sizeof(disabled));
631: #endif
632: 
633:     /* We need destination address for udp packets in both ipv6 and ipv4 */
634: 
635: /* On FreeBSD this option seems to be called like so */
636: #ifndef IPV6_RECVPKTINFO
637: #define IPV6_RECVPKTINFO IPV6_PKTINFO
638: #endif
639: 
640:     int enabled = 1;
641:     if (setsockopt(listenFd, IPPROTO_IPV6, IPV6_RECVPKTINFO, (void *) &enabled, sizeof(enabled)) == -1) {
642:         if (errno == 92) {
643:             // Linux ipv4
644:         #ifdef IP_PKTINFO
645:             if (setsockopt(listenFd, IPPROTO_IP, IP_PKTINFO, (void *) &enabled, sizeof(enabled)) != 0) {
646:                 printf("Error setting IPv4 pktinfo!\n");
647:             }
648:             // FreeBSD ipv4
649:         #elif IP_RECVDSTADDR
650:             if (setsockopt(listenFd, IPPROTO_IP, IP_RECVDSTADDR, (void *) &enabled, sizeof(enabled)) != 0) {
651:                 printf("Error setting IPv4 pktinfo!\n");
652:             }
653:         #endif
654:         } else {
655:             printf("Error setting IPv6 pktinfo!\n");
656:         }
657:     }
658: 
659:     /* These are used for getting the ECN */
660:     if (setsockopt(listenFd, IPPROTO_IPV6, IPV6_RECVTCLASS, (void *) &enabled, sizeof(enabled)) == -1) {
661:         if (errno == 92) {
662:             if (setsockopt(listenFd, IPPROTO_IP, IP_RECVTOS, (void *) &enabled, sizeof(enabled)) != 0) {
663:                 printf("Error setting IPv4 ECN!\n");
664:             }
665:         } else {
666:             printf("Error setting IPv6 ECN!\n");
667:         }
668:     }
669: 
670:     /* We bind here as well */
671:     if (bind(listenFd, listenAddr->ai_addr, (socklen_t) listenAddr->ai_addrlen)) {
672:         bsd_close_socket(listenFd);
673:         freeaddrinfo(result);
674:         return LIBUS_SOCKET_ERROR;
675:     }
676: 
677:     freeaddrinfo(result);
678:     return listenFd;
679: }
