85: void us_internal_timer_sweep(struct us_loop_t *loop) {
86:     struct us_internal_loop_data_t *loop_data = &loop->data;
87:     /* For all socket contexts in this loop */
88:     for (loop_data->iterator = loop_data->head; loop_data->iterator; loop_data->iterator = loop_data->iterator->next) {
89: 
90:         struct us_socket_context_t *context = loop_data->iterator;
91: 
92:         /* Update this context's timestamps (this could be moved to loop and done once) */
93:         context->global_tick++;
94:         unsigned char short_ticks = context->timestamp = context->global_tick % 240;
95:         unsigned char long_ticks = context->long_timestamp = (context->global_tick / 15) % 240;
96: 
97:         /* Begin at head */
98:         struct us_socket_t *s = context->head_sockets;
99:         while (s) {
100:             /* Seek until end or timeout found (tightest loop) */
101:             while (1) {
102:                 /* We only read from 1 random cache line here */
103:                 if (short_ticks == s->timeout || long_ticks == s->long_timeout) {
104:                     break;
105:                 }
106: 
107:                 /* Did we reach the end without a find? */
108:                 if ((s = s->next) == 0) {
109:                     goto next_context;
110:                 }
111:             }
112: 
113:             /* Here we have a timeout to emit (slow path) */
114:             context->iterator = s;
115: 
116:             if (short_ticks == s->timeout) {
117:                 s->timeout = 255;
118:                 context->on_socket_timeout(s);
119:             }
120: 
121:             if (context->iterator == s && long_ticks == s->long_timeout) {
122:                 s->long_timeout = 255;
123:                 context->on_socket_long_timeout(s);
124:             }   
125: 
126:             /* Check for unlink / link (if the event handler did not modify the chain, we step 1) */
127:             if (s == context->iterator) {
128:                 s = s->next;
129:             } else {
130:                 /* The iterator was changed by event handler */
131:                 s = context->iterator;
132:             }
133:         }
134:         /* We always store a 0 to context->iterator here since we are no longer iterating this context */
135:         next_context:
136:         context->iterator = 0;
137:     }
138: }
