35: void us_listen_socket_close(int ssl, struct us_listen_socket_t *ls) {
36:     /* us_listen_socket_t extends us_socket_t so we close in similar ways */
37:     if (!us_socket_is_closed(0, &ls->s)) {
38:         us_internal_socket_context_unlink_listen_socket(ls->s.context, ls);
39:         us_poll_stop((struct us_poll_t *) &ls->s, ls->s.context->loop);
40:         bsd_close_socket(us_poll_fd((struct us_poll_t *) &ls->s));
41: 
42:         /* Link this socket to the close-list and let it be deleted after this iteration */
43:         ls->s.next = ls->s.context->loop->data.closed_head;
44:         ls->s.context->loop->data.closed_head = &ls->s;
45: 
46:         /* Any socket with prev = context is marked as closed */
47:         ls->s.prev = (struct us_socket_t *) ls->s.context;
48:     }
49: 
50:     /* We cannot immediately free a listen socket as we can be inside an accept loop */
51: }
