53: void us_socket_context_close(int ssl, struct us_socket_context_t *context) {
54:     /* Begin by closing all listen sockets */
55:     struct us_listen_socket_t *ls = context->head_listen_sockets;
56:     while (ls) {
57:         struct us_listen_socket_t *nextLS = (struct us_listen_socket_t *) ls->s.next;
58:         us_listen_socket_close(ssl, ls);
59:         ls = nextLS;
60:     }
61: 
62:     /* Then close all regular sockets */
63:     struct us_socket_t *s = context->head_sockets;
64:     while (s) {
65:         struct us_socket_t *nextS = s->next;
66:         us_socket_close(ssl, s, 0, 0);
67:         s = nextS;
68:     }
69: }
