71: void us_internal_socket_context_unlink_listen_socket(struct us_socket_context_t *context, struct us_listen_socket_t *ls) {
72:     /* We have to properly update the iterator used to sweep sockets for timeouts */
73:     if (ls == (struct us_listen_socket_t *) context->iterator) {
74:         context->iterator = ls->s.next;
75:     }
76: 
77:     if (ls->s.prev == ls->s.next) {
78:         context->head_listen_sockets = 0;
79:     } else {
80:         if (ls->s.prev) {
81:             ls->s.prev->next = ls->s.next;
82:         } else {
83:             context->head_listen_sockets = (struct us_listen_socket_t *) ls->s.next;
84:         }
85:         if (ls->s.next) {
86:             ls->s.next->prev = ls->s.prev;
87:         }
88:     }
89: }
