91: void us_internal_socket_context_unlink_socket(struct us_socket_context_t *context, struct us_socket_t *s) {
92:     /* We have to properly update the iterator used to sweep sockets for timeouts */
93:     if (s == context->iterator) {
94:         context->iterator = s->next;
95:     }
96: 
97:     if (s->prev == s->next) {
98:         context->head_sockets = 0;
99:     } else {
100:         if (s->prev) {
101:             s->prev->next = s->next;
102:         } else {
103:             context->head_sockets = s->next;
104:         }
105:         if (s->next) {
106:             s->next->prev = s->prev;
107:         }
108:     }
109: }
