112: void us_internal_socket_context_link_listen_socket(struct us_socket_context_t *context, struct us_listen_socket_t *ls) {
113:     ls->s.context = context;
114:     ls->s.next = (struct us_socket_t *) context->head_listen_sockets;
115:     ls->s.prev = 0;
116:     if (context->head_listen_sockets) {
117:         context->head_listen_sockets->s.prev = &ls->s;
118:     }
119:     context->head_listen_sockets = ls;
