203: /* Options is currently only applicable for SSL - this will change with time (prefer_low_memory is one example) */
204: struct us_socket_context_t *us_create_socket_context(int ssl, struct us_loop_t *loop, int context_ext_size, struct us_socket_context_options_t options) {
205: #ifndef LIBUS_NO_SSL
206:     if (ssl) {
207:         /* This function will call us, again, with SSL = false and a bigger ext_size */
208:         return (struct us_socket_context_t *) us_internal_create_ssl_socket_context(loop, context_ext_size, options);
209:     }
210: #endif
211: 
212:     /* This path is taken once either way - always BEFORE whatever SSL may do LATER.
213:      * context_ext_size will however be modified larger in case of SSL, to hold SSL extensions */
214: 
215:     struct us_socket_context_t *context = malloc(sizeof(struct us_socket_context_t) + context_ext_size);
216:     context->loop = loop;
217:     context->head_sockets = 0;
218:     context->head_listen_sockets = 0;
219:     context->iterator = 0;
220:     context->next = 0;
221:     context->is_low_prio = default_is_low_prio_handler;
222: 
223:     /* Begin at 0 */
224:     context->timestamp = 0;
225:     context->long_timestamp = 0;
226:     context->global_tick = 0;
227: 
228:     /* Some new events must be set to null for backwards compatibility */
229:     context->on_pre_open = 0;
230: 
231:     us_internal_loop_link(loop, context);
232: 
233:     /* If we are called from within SSL code, SSL code will make further changes to us */
234:     return context;
235: }
