272:     ls->s.context = context;
273:     ls->s.timeout = 255;
274:     ls->s.long_timeout = 255;
275:     ls->s.low_prio_state = 0;
276:     ls->s.next = 0;
277:     us_internal_socket_context_link_listen_socket(context, ls);
278: 
279:     ls->socket_ext_size = socket_ext_size;
280: 
281:     return ls;
282: }
