385: /* Note: This will set timeout to 0 */
386: struct us_socket_t *us_socket_context_adopt_socket(int ssl, struct us_socket_context_t *context, struct us_socket_t *s, int ext_size) {
387: #ifndef LIBUS_NO_SSL
388:     if (ssl) {
389:         return (struct us_socket_t *) us_internal_ssl_socket_context_adopt_socket((struct us_internal_ssl_socket_context_t *) context, (struct us_internal_ssl_socket_t *) s, ext_size);
390:     }
391: #endif
392: 
393:     /* Cannot adopt a closed socket */
394:     if (us_socket_is_closed(ssl, s)) {
395:         return s;
396:     }
397: 
398:     if (s->low_prio_state != 1) {
399:         /* This properly updates the iterator if in on_timeout */
400:         us_internal_socket_context_unlink_socket(s->context, s);
401:     }
402: 
403:     struct us_socket_t *new_s = (struct us_socket_t *) us_poll_resize(&s->p, s->context->loop, sizeof(struct us_socket_t) + ext_size);
404:     new_s->timeout = 255;
405:     new_s->long_timeout = 255;
406: 
407:     if (new_s->low_prio_state == 1) {
408:         /* update pointers in low-priority queue */
409:         if (!new_s->prev) new_s->context->loop->data.low_prio_head = new_s;
410:         else new_s->prev->next = new_s;
411: 
412:         if (new_s->next) new_s->next->prev = new_s;
413:     } else {
414:         us_internal_socket_context_link_socket(context, new_s);
415:     }
416: 
417:     return new_s;
418: }
